// Generated by MCSuperMods: the event actions of msm_runtime as plain helpers.
package msm_test;

import com.mojang.brigadier.exceptions.CommandSyntaxException;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import net.minecraft.commands.CommandSourceStack;
import net.minecraft.commands.arguments.blocks.BlockStateParser;
import net.minecraft.commands.functions.CommandFunction;
import net.minecraft.core.BlockPos;
import net.minecraft.core.particles.ParticleType;
import net.minecraft.core.particles.SimpleParticleType;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.Identifier;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.permissions.LevelBasedPermissionSet;
import net.minecraft.sounds.SoundEvent;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.Vec3;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * The actions an event runs, called from the generated event methods. Each takes the owner
 * (the id of the block, item or entity whose event runs) for log messages.
 */
public final class Actions {
    /** {@code trigger_event} chains nest at most this deep; the fired event is depth 1. */
    public static final int MAX_DEPTH = 16;

    private static final Logger LOGGER = LoggerFactory.getLogger("msm_test");
    private static final Map<String, Optional<BlockState>> STATES = new ConcurrentHashMap<>();

    private Actions() {}

    /** Whether an event at {@code depth} is too deep to run; logs once when it is. */
    public static boolean tooDeep(String owner, String event, int depth) {
        if (depth <= MAX_DEPTH) {
            return false;
        }
        LOGGER.error("{}: event chain deeper than {} stopped before {}", owner, MAX_DEPTH, event);
        return true;
    }

    /**
     * Runs a data pack function at {@code origin} with permission level 2, as {@code as} when there is one: the
     * player, or in a block step event without a player the stepping entity.
     */
    public static void runFunction(String owner, ServerLevel level, Vec3 origin, Entity as, String id) {
        MinecraftServer server = level.getServer();
        Optional<CommandFunction<CommandSourceStack>> function = server.getFunctions().get(Identifier.parse(id));
        if (function.isEmpty()) {
            LOGGER.error("{}: unknown function {}", owner, id);
            return;
        }
        CommandSourceStack source = server.createCommandSourceStack()
                .withLevel(level)
                .withPosition(origin)
                .withPermission(LevelBasedPermissionSet.GAMEMASTER) // permission level 2, as for function tags
                .withSuppressedOutput();
        if (as != null) {
            source = source.withEntity(as).withRotation(as.getRotationVector());
        }
        server.getFunctions().execute(function.get(), source);
    }

    /** Server-side particles at {@code origin}. */
    public static void spawnParticle(String owner, ServerLevel level, Vec3 origin, String id, int count, float spread, float speed) {
        Identifier particle = Identifier.parse(id);
        ParticleType<?> type = BuiltInRegistries.PARTICLE_TYPE.getValue(particle);
        if (!(type instanceof SimpleParticleType simple) || !BuiltInRegistries.PARTICLE_TYPE.containsKey(particle)) {
            LOGGER.error("{}: {} is not a particle type without options", owner, id);
            return;
        }
        level.sendParticles(simple, origin.x, origin.y, origin.z, count, spread, spread, spread, speed);
    }

    /** Places a block state at an offset from {@code base}. */
    public static void setBlockState(String owner, ServerLevel level, BlockPos base, String state, int dx, int dy, int dz) {
        Optional<BlockState> parsed = parseState(state);
        if (parsed.isEmpty()) {
            LOGGER.error("{}: invalid block state '{}'", owner, state);
            return;
        }
        level.setBlockAndUpdate(base.offset(dx, dy, dz), parsed.get());
    }

    /** Parses a block state string once; blocks of every mod exist by the time events run. */
    private static Optional<BlockState> parseState(String state) {
        return STATES.computeIfAbsent(state, s -> {
            try {
                return Optional.of(BlockStateParser.parseForBlock(BuiltInRegistries.BLOCK, s, false).blockState());
            } catch (CommandSyntaxException e) {
                return Optional.empty();
            }
        });
    }

    /** Gives the player an item stack, dropping what does not fit; nothing without a player. */
    public static void giveItem(String owner, ServerLevel level, Player player, String id, int count) {
        if (player == null) {
            return;
        }
        Optional<Item> item = BuiltInRegistries.ITEM.getOptional(Identifier.parse(id));
        if (item.isEmpty()) {
            LOGGER.error("{}: unknown item {}", owner, id);
            return;
        }
        int left = count;
        int max = item.get().getDefaultMaxStackSize();
        while (left > 0) {
            ItemStack stack = new ItemStack(item.get(), Math.min(left, max));
            left -= stack.getCount();
            if (!player.addItem(stack) && !stack.isEmpty()) {
                Block.popResource(level, player.blockPosition(), stack);
            }
        }
    }

    /** Plays a sound event at {@code origin}: neutral for entity events, blocks otherwise. */
    public static void playSound(String owner, ServerLevel level, Vec3 origin, Entity entity, String id, float volume, float pitch) {
        Optional<SoundEvent> sound = BuiltInRegistries.SOUND_EVENT.getOptional(Identifier.parse(id));
        if (sound.isEmpty()) {
            LOGGER.error("{}: unknown sound {}", owner, id);
            return;
        }
        SoundSource source = entity != null ? SoundSource.NEUTRAL : SoundSource.BLOCKS;
        level.playSound(null, origin.x, origin.y, origin.z, sound.get(), source, volume, pitch);
    }
}
